import{_ as r,o as e,c as d,a2 as o}from"./chunks/framework.kOe0DhAP.js";const m=JSON.parse('{"title":"生态全景","description":"Microsphere Projects 与外部技术栈的对接关系","frontmatter":{"title":"生态全景","description":"Microsphere Projects 与外部技术栈的对接关系","outline":[2,3]},"headers":[],"relativePath":"ecosystem.md","filePath":"ecosystem.md","lastUpdated":null}'),a={name:"ecosystem.md"};function s(i,t,c,h,p,n){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="生态全景" tabindex="-1">生态全景 <a class="header-anchor" href="#生态全景" aria-label="Permalink to &quot;生态全景&quot;">​</a></h1><p>Microsphere 不是一个封闭框架，它的绝大多数项目都是<strong>围绕既有技术栈做增强</strong>。这一页列出它与外部生态的对接点。</p><h2 id="对接的技术栈" tabindex="-1">对接的技术栈 <a class="header-anchor" href="#对接的技术栈" aria-label="Permalink to &quot;对接的技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>外部技术</th><th>对接项目</th></tr></thead><tbody><tr><td><strong>核心框架</strong></td><td>Spring Framework 4.3 – 7.0</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td></td><td>Spring Boot 2.0 – 4.1</td><td><a href="/projects/microsphere-spring-boot">microsphere-spring-boot</a></td></tr><tr><td></td><td>Spring Cloud Hoxton – 2025.x</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td><strong>服务注册与发现</strong></td><td>Alibaba Nacos</td><td><a href="/projects/microsphere-nacos">microsphere-nacos</a></td></tr><tr><td></td><td>Netflix Eureka</td><td><a href="/projects/microsphere-netflix">microsphere-netflix</a></td></tr><tr><td></td><td>Consul / Zookeeper</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td></td><td>etcd</td><td><a href="/projects/microsphere-etcd">microsphere-etcd</a></td></tr><tr><td><strong>RPC 与网关</strong></td><td>Apache Dubbo</td><td><a href="/projects/microsphere-dubbo">microsphere-dubbo</a></td></tr><tr><td></td><td>Spring Cloud Gateway（WebFlux / MVC）</td><td><a href="/projects/microsphere-gateway">microsphere-gateway</a></td></tr><tr><td></td><td>OpenFeign</td><td><a href="/projects/microsphere-spring-cloud">microsphere-spring-cloud</a></td></tr><tr><td><strong>数据访问</strong></td><td>MyBatis</td><td><a href="/projects/microsphere-mybatis">microsphere-mybatis</a></td></tr><tr><td></td><td>Hibernate ORM 5.0 – 7.3</td><td><a href="/projects/microsphere-hibernate">microsphere-hibernate</a></td></tr><tr><td></td><td>Alibaba Druid</td><td><a href="/projects/microsphere-alibaba-druid">microsphere-alibaba-druid</a></td></tr><tr><td></td><td>P6Spy</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td><strong>缓存</strong></td><td>Spring Data Redis 2.1 – 3.5</td><td><a href="/projects/microsphere-redis">microsphere-redis</a></td></tr><tr><td></td><td>Apache Kafka（Redis 复制）</td><td><a href="/projects/microsphere-redis">microsphere-redis</a></td></tr><tr><td><strong>韧性与流控</strong></td><td>Alibaba Sentinel</td><td><a href="/projects/microsphere-alibaba-sentinel">microsphere-alibaba-sentinel</a></td></tr><tr><td></td><td>Resilience4j 1.3 – 2.4</td><td><a href="/projects/microsphere-resilience4j">microsphere-resilience4j</a></td></tr><tr><td><strong>可观测性</strong></td><td>Micrometer</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td></td><td>Prometheus</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td></td><td>OpenTelemetry Instrumentation BOM</td><td><a href="/projects/microsphere-observability">microsphere-observability</a></td></tr><tr><td><strong>日志</strong></td><td>JUL / Log4j / Log4j2 / Logback / SLF4J</td><td><a href="/projects/microsphere-logging">microsphere-logging</a></td></tr><tr><td><strong>Web 容器</strong></td><td>Apache Tomcat</td><td><a href="/projects/microsphere-tomcat">microsphere-tomcat</a></td></tr><tr><td><strong>企业规范</strong></td><td>Java EE / Jakarta EE / MicroProfile</td><td><a href="/projects/microsphere-java-enterprise">EE</a> · <a href="/projects/microsphere-jakarta">Jakarta</a> · <a href="/projects/microsphere-microprofile">MicroProfile</a></td></tr><tr><td><strong>依赖注入</strong></td><td>Google Guice</td><td><a href="/projects/microsphere-spring">microsphere-spring</a></td></tr><tr><td><strong>云平台</strong></td><td>AWS（可用区发现）</td><td><a href="/projects/microsphere-multiactive">microsphere-multiactive</a></td></tr></tbody></table><h2 id="与其它增强库的差异" tabindex="-1">与其它增强库的差异 <a class="header-anchor" href="#与其它增强库的差异" aria-label="Permalink to &quot;与其它增强库的差异&quot;">​</a></h2><p>Microsphere 的定位是<strong>增量增强而非替代</strong>。三个显著特征：</p><ol><li><strong>零侵入</strong> — 大部分能力通过拦截管道、自动配置与事件机制织入，不需要修改既有代码。 例如 <code>@EnableP6DataSource</code> 只需一个注解，即可包裹全部 DataSource Bean。</li><li><strong>可裁剪</strong> — 每个 Maven 模块都可独立引入，不会强制带入整套依赖。</li><li><strong>长周期兼容</strong> — 通过兼容 shim 让同一套代码横跨 Spring Boot 2.x 至 4.x，避免为升级而分叉维护。</li></ol><h2 id="发布与制品" tabindex="-1">发布与制品 <a class="header-anchor" href="#发布与制品" aria-label="Permalink to &quot;发布与制品&quot;">​</a></h2><ul><li>全部制品发布至 <strong>Maven Central</strong>，Group ID 为 <code>io.github.microsphere-projects</code></li><li>自 <code>microsphere-build</code> 0.2.0 起使用 Central Publisher Portal（OSSRH 已于 2025-06-30 下线）</li><li>每个仓库都配置了 Maven Build 与 Codecov 工作流</li></ul><h2 id="文档资源" tabindex="-1">文档资源 <a class="header-anchor" href="#文档资源" aria-label="Permalink to &quot;文档资源&quot;">​</a></h2><p>每个子项目都提供双语文档（English 默认，中文位于 <code>zh/</code> 目录），并按发布分支组织：</p><table tabindex="0"><thead><tr><th>资源</th><th>位置</th></tr></thead><tbody><tr><td>仓库内用户文档</td><td><code>docs/user-guide/</code> · <code>docs/developer-guide/</code></td></tr><tr><td>智能问答文档</td><td>各仓库对应的 DeepWiki 与 Zread 空间</td></tr><tr><td>JavaDoc</td><td>javadoc.io（按模块独立发布）</td></tr><tr><td>Wiki</td><td>各仓库 GitHub Wiki</td></tr></tbody></table>',12)])])}const g=r(a,[["render",s]]);export{m as __pageData,g as default};
